const parseBookmarkUrl = (value: string): URL => {
  const parsed = new URL(value.trim());

  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    throw new TypeError("Bookmark URL must use HTTP or HTTPS.");
  }

