import { Component, type ErrorInfo, type ReactNode } from 'react';

export type AppStatus = 'loading' | 'error' | 'empty';

interface AppProps {
  status?: AppStatus;
  errorMessage?: string;
  onRetry?: () => void;
}

export function App({
  status = 'loading',
  errorMessage = 'Your bookmarks could not be loaded.',
  onRetry,
}: AppProps) {
  return (
    <main {...(status === 'empty' ? { 'data-harness-ready': 'true' } : {})}>
      <header>
        <p>Trove</p>
        <h1>Your bookmarks, kept close.</h1>
      </header>

      <section aria-labelledby="library-heading">
        <h2 id="library-heading">Library</h2>

        {status === 'loading' && (
          <p role="status" aria-live="polite">
            Loading your bookmarks…
          </p>
        )}

        {status === 'error' && (
          <div role="alert">
            <p>{errorMessage}</p>
            {onRetry && (
              <button type="button" onClick={onRetry}>
                Try again
              </button>
            )}
          </div>
        )}

        {status === 'empty' && (
          <div>
            <h3>Your library is empty</h3>
            <p>Save your first bookmark to start building your collection.</p>
          </div>
        )}
      </section>
    </main>
  );
}

interface AppErrorBoundaryProps {
  children: ReactNode;
}

interface AppErrorBoundaryState {
  hasError: boolean;
}

export class AppErrorBoundary extends Component<
  AppErrorBoundaryProps,
  AppErrorBoundaryState
> {
  public state: AppErrorBoundaryState = { hasError: false };

  public static getDerivedStateFromError(): AppErrorBoundaryState {
    return { hasError: true };
  }

  public componentDidCatch(error: Error, info: ErrorInfo): void {
    console.error('The bookmark application could not be rendered.', error, info);
  }

  public render(): ReactNode {
    if (this.state.hasError) {
      return (
        <main>
          <h1>Trove</h1>
          <div role="alert">
            <h2>Something went wrong</h2>
            <p>Refresh the page to return to your bookmarks.</p>
          </div>
        </main>
      );
    }

    return this.props.children;
  }
}

export default App;

