    return { hasError: true };
  }

  public componentDidCatch(error: Error, info: ErrorInfo): void {
    console.error('The bookmark application could not be rendered.', error, info);
  }

  public render(): ReactNode {
    if (this.state.hasError) {
      return (
        <main>
          <h1>Trove</h1>
          <div role="alert">
            <h2>Something went wrong</h2>
            <p>Refresh the page to return to your bookmarks.</p>
          </div>
        </main>
      );
    }

    return this.props.children;
  }
}

export default App;
import { useEffect, useState } from 'react';

import type { SortOrder, Tag } from '../../../shared/contracts.js';

export interface LibraryControlsProps {
  query: string;
  selectedTags: readonly string[];
  sort: SortOrder;
  tags: readonly Tag[];
  onQueryChange: (query: string) => void;
  onTagsChange: (tags: string[]) => void;
  onSortChange: (sort: SortOrder) => void;
}

export function LibraryControls({
  query,
  selectedTags,
  sort,
  tags,
  onQueryChange,
  onTagsChange,
  onSortChange,
}: LibraryControlsProps) {
  const [draftQuery, setDraftQuery] = useState(query);

  useEffect(() => setDraftQuery(query), [query]);
  useEffect(() => {
    if (draftQuery === query) return;
    const timer = window.setTimeout(() => onQueryChange(draftQuery), 250);
    return () => window.clearTimeout(timer);
  }, [draftQuery, onQueryChange, query]);

  const toggleTag = (normalizedName: string, selected: boolean) => {
    onTagsChange(
      selected
        ? [...selectedTags, normalizedName]
        : selectedTags.filter((tag) => tag !== normalizedName),
    );
  };

  return (
    <section aria-label="Find and organize bookmarks">
      <label htmlFor="bookmark-search">Search bookmarks</label>
      <input
        id="bookmark-search"
        type="search"
        value={draftQuery}
        onChange={(event) => setDraftQuery(event.target.value)}
      />

      {tags.length > 0 && (
        <fieldset>
          <legend>Filter by tags</legend>
          {tags.map((tag) => (
            <label key={tag.normalizedName}>
              <input
                type="checkbox"
                checked={selectedTags.includes(tag.normalizedName)}
                onChange={(event) => toggleTag(tag.normalizedName, event.target.checked)}
              />
              {tag.name} ({tag.bookmarkCount})
            </label>
          ))}
        </fieldset>
      )}

      <label htmlFor="bookmark-sort">Sort bookmarks</label>
      <select
        id="bookmark-sort"
        value={sort}
        onChange={(event) => onSortChange(event.target.value as SortOrder)}
      >
        <option value="newest">Newest saved</option>
        <option value="oldest">Oldest saved</option>
        <option value="title">Title A–Z</option>
      </select>

      {selectedTags.length > 0 && (
        <div aria-label="Active filters">
          {selectedTags.map((normalizedName) => {
            const label = tags.find((tag) => tag.normalizedName === normalizedName)?.name ?? normalizedName;
            return (
              <button
                key={normalizedName}
                type="button"
                aria-label={`Remove ${label} filter`}
                onClick={() => toggleTag(normalizedName, false)}
              >
                {label} ×
              </button>
            );
          })}
        </div>
      )}
    </section>
  );
}
import type { Bookmark, ReadingState } from '../../../shared/contracts.js';

export interface BookmarkCardProps {
  bookmark: Bookmark;
  onReadingStateChange?: (bookmark: Bookmark, readingState: ReadingState) => void;
}

const readingStateLabels: Record<ReadingState, string> = {
  untracked: 'Untracked',
  to_read: 'To Read',
  read: 'Read',
};

const savedDateFormatter = new Intl.DateTimeFormat('en-US', {
  dateStyle: 'medium',
  timeZone: 'UTC',
});

export function formatSavedDate(timestamp: string): string {
  const date = new Date(timestamp);
  return Number.isNaN(date.getTime()) ? timestamp : savedDateFormatter.format(date);
}

export function BookmarkCard({ bookmark, onReadingStateChange }: BookmarkCardProps) {
  const titleId = `bookmark-title-${bookmark.id}`;

  return (
    <article aria-labelledby={titleId}>
      <header>
        <h3 id={titleId}>
          <a href={bookmark.url} target="_blank" rel="noopener noreferrer">
            {bookmark.title}
          </a>
        </h3>
        <p>{bookmark.url}</p>
      </header>

      {bookmark.description && <p>{bookmark.description}</p>}

      <dl>
        <div>
          <dt>Saved</dt>
          <dd>
            <time dateTime={bookmark.createdAt}>{formatSavedDate(bookmark.createdAt)}</time>
          </dd>
        </div>
        <div>
          <dt>Reading status</dt>
          <dd>{readingStateLabels[bookmark.readingState]}</dd>
        </div>
      </dl>

      {bookmark.tags.length > 0 && (
        <ul aria-label={`Tags for ${bookmark.title}`}>
          {bookmark.tags.map((tag) => (
            <li key={tag}>{tag}</li>
          ))}
        </ul>
      )}

      {onReadingStateChange && (
        <button
          type="button"
          onClick={() =>
            onReadingStateChange(
              bookmark,
              bookmark.readingState === 'to_read' ? 'read' : 'to_read',
            )
          }
        >
          {bookmark.readingState === 'to_read' ? 'Mark as Read' : 'Mark as To Read'}
        </button>
      )}
    </article>
  );
}

export default BookmarkCard;

