    return <BookmarkListEmpty state={emptyState} onClearCriteria={onClearCriteria} />;
  }

  return (
    <ul aria-label="Bookmarks">
      {bookmarks.map((bookmark) => (
        <li key={bookmark.id}>
          <BookmarkCard
            bookmark={bookmark}
            onReadingStateChange={onReadingStateChange}
            onEdit={onEdit}
            onDelete={onDelete}
          />
        </li>
      ))}
    </ul>
  );
}

export default BookmarkList;

