  z-index: 2;
}

main > section[aria-labelledby='add-bookmark-heading'] > h2 {
  margin-bottom: var(--space-5);
  font-family: var(--font-display);
  font-size: 2rem;
}

form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-4);
}

form > div {
  min-width: 0;
}

form > div:nth-of-type(1),
form > div:nth-of-type(3),
form > div:last-child,
form > [role='alert'],
form > [role='status'] {
  grid-column: 1 / -1;
}

form label,
section[aria-label='Find and organize bookmarks'] > label,
fieldset legend {
  display: block;
  margin-bottom: var(--space-2);
  color: var(--color-ink);
  font-size: var(--text-sm);
