  gap: var(--space-3);
  padding-top: var(--space-2);
}

form > div:last-child button:first-child:not(:last-child) {
  border-color: var(--color-line-strong);
  background: transparent;
  color: var(--color-ink);
}

div[role='tablist'] {
  display: inline-flex;
  gap: var(--space-1);
